#!/usr/bin/env python3
"""Check lossless repository relocation and regenerate stable public entry points.

Read-only by default; --generate changes only the three public shell launchers.
No networking, no VPN execution and no credentials are required.
"""
from pathlib import Path
import argparse
import re
import subprocess

BASELINE = 'b37948a924f72cc06b577a0e5a3cf3f1f6e9170e'
ARCHIVE = set('build desktop electron-builder.json index.html makefile package-lock.json package.json public scripts src test tsconfig.json vite.config.ts'.split())
MIRRORS = ('diagnostic_profile.sh', 'diagnostics-release.tsv', 'network-fixtures.sha256', 'network-fixtures.tsv')
PRIMARY = {'st.sh': 'diagnostics/st.sh', 'macdiag-core.sh': 'diagnostics/macdiag-core.sh', 'vpn.sh': 'vpn/vpn.sh'}
ROOT = Path(__file__).resolve().parents[1]
TEMPLATE = r'''#!/bin/bash
# Stable entry point; canonical implementation: @TARGET@
# Generated by .github/repository_layout.py. No privilege escalation here.
component_entry() (
  set +x
  set -eu
  set -o pipefail
  export PATH=/usr/bin:/bin:/usr/sbin:/sbin LC_ALL=C
  unset BASH_ENV ENV CDPATH PERL5OPT PERL5LIB PERLLIB PERL_UNICODE
  umask 077
  local target='@TARGET@' source_ref='@REF@' expected_blob='@BLOB@'
  local here='' work='' actual='' result=0
  if [ -n "${BASH_SOURCE[0]:-}" ] && [ -f "${BASH_SOURCE[0]}" ]; then
    here=$(CDPATH= cd -- "$(/usr/bin/dirname -- "${BASH_SOURCE[0]}")" && pwd -P)
    if [ -f "$here/$target" ] && [ ! -L "$here/$target" ]; then
      exec /bin/bash "$here/$target" "$@"
    fi
  fi
  work=$(/usr/bin/mktemp -d /tmp/macos-entry.XXXXXX)
  trap '/bin/rm -rf "$work"' EXIT
  trap 'exit 130' INT
  trap 'exit 143' TERM
  (
    ulimit -f 2048
    /usr/bin/curl -q -fLsS --proto '=https' --proto-redir '=https' \
      --connect-timeout 15 --max-time 120 --max-filesize 1048576 --max-redirs 3 \
      "https://raw.githubusercontent.com/pioner22/MacOS/$source_ref/$target" \
      -o "$work/entry.sh" </dev/null
  ) || { printf '%s\n' 'ОШИБКА: загрузчик не скачан полностью; выполнение отменено.' >&2; exit 1; }
  # Exact Git blob identity is an integrity check, NOT a publisher signature.
  # The canonical installer retains its own existing SHA-256 verification.
  actual=$(/usr/bin/perl -f -MDigest::SHA=sha1_hex -e '
    open my $f,"<",$ARGV[0] or exit 1; binmode $f;
    my $data=""; my $n=read($f,$data,1048577);
    defined($n) && $n>0 && $n<=1048576 or exit 1;
    print sha1_hex("blob ".length($data)."\0".$data);
  ' "$work/entry.sh" </dev/null) || exit 1
  [ "$actual" = "$expected_blob" ] || {
    printf '%s\n' 'ОШИБКА: скачанный файл не совпал с закреплённым Git-объектом.' >&2; exit 1;
  }
  /bin/bash -n "$work/entry.sh" || exit 1
  /bin/bash "$work/entry.sh" "$@" || result=$?
  exit "$result"
)
# Invocation last: an incomplete function body cannot launch a component.
component_entry "$@"
'''


def destination(path):
    top = path.split('/')[0]
    if top == '.github': return None  # workflows intentionally get new paths
    if path in ('.gitignore', 'LICENSE'): return path
    if path == 'README.md': return '.archive/yagodka-client/README.original.md'
    if top in ARCHIVE: return '.archive/yagodka-client/' + path
    if top == 'tests':
        tail = path.split('/', 1)[1]
        return ('vpn/' if tail.startswith('test_vpn_') else 'diagnostics/') + path
    if top.startswith(('VPN_', 'vpn-', 'test_vpn_')) or top == 'vpn.sh':
        return 'vpn/' + path
    return 'diagnostics/' + path


def git_tree(ref, root=ROOT):
    raw = subprocess.check_output(['git', 'ls-tree', '-rz', ref], cwd=root)
    values = {}
    for row in raw.split(b'\0'):
        if row:
            meta, path = row.split(b'\t', 1)
            mode, kind, digest = meta.decode().split()
            values[path.decode()] = (mode, kind, digest)
    return values


def launcher(target, ref, blob):
    if target not in PRIMARY.values() or not re.fullmatch('[a-f0-9]{40}', ref) or not re.fullmatch('[a-f0-9]{40}', blob):
        raise ValueError('Invalid fixed launcher target/ref/blob')
    return TEMPLATE.replace('@TARGET@', target).replace('@REF@', ref).replace('@BLOB@', blob)


def check(root=ROOT, audit_relocation=False):
    old, new = git_tree(BASELINE, root), git_tree('HEAD', root)
    failures = []
    for path, identity in old.items():
        target = destination(path)
        if target and (new.get(target, ())[:2] != identity[:2] or (audit_relocation and new.get(target) != identity)):
            failures.append('Missing or changed relocated object: %s -> %s' % (path, target))
    for path in MIRRORS:
        if new.get(path) != new.get('diagnostics/' + path):
            failures.append('Raw-compatible mirror diverged: ' + path)
    for name, target in PRIMARY.items():
        text = (root / name).read_text()
        match = re.search(r"source_ref='([a-f0-9]{40})' expected_blob='([a-f0-9]{40})'", text)
        if not match or text != launcher(target, *match.groups()):
            failures.append('Invalid/generated launcher mismatch: ' + name)
            continue
        if git_tree(match.group(1), root).get(target, (None,None,None))[2] != match.group(2):
            failures.append('Pinned target does not match launcher: ' + name)
    # Original aliases remain byte-identical because old clients may source them.
    for path, identity in old.items():
        if '/' not in path and path.endswith('.sh') and path not in PRIMARY and new.get(path) != identity:
            failures.append('Historical entry point changed: ' + path)
    allowed = {'.github', '.archive', '.gitignore', 'LICENSE', 'README.md', 'diagnostics', 'vpn'} | set(MIRRORS)
    allowed.update(p for p in old if '/' not in p and p.endswith('.sh'))
    for path in new:
        if path.split('/')[0] not in allowed:
            failures.append('Unexpected root material: ' + path)
    if failures: raise ValueError('\n'.join(failures))
    return sum(destination(p) is not None for p in old)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--generate', metavar='SOURCE_COMMIT')
    parser.add_argument('--audit-relocation', action='store_true', help='One-time exact blob audit against the pre-move snapshot')
    args = parser.parse_args()
    if args.generate:
        pinned = git_tree(args.generate)
        for name, target in PRIMARY.items():
            (ROOT / name).write_text(launcher(target, args.generate, pinned[target][2]))
        print('Generated three entry points; review, test and commit them together.')
    else:
        print('PASS: %d relocated paths and entry points verified (exact blob audit=%s).' %
              (check(audit_relocation=args.audit_relocation), args.audit_relocation))

if __name__ == '__main__': main()
